#include <fstream>
#include <iostream>
#include <vector>
#include <array>
using namespace std;using I=long long;
int main(int argc,char**argv){ifstream b(argv[1]),c(argv[2]);int total;b>>total;vector<vector<unsigned>> bank;for(int k=0;k<total;k++){int n;b>>n;vector<unsigned>a(n);for(auto&x:a)b>>x;bank.push_back(a);}int ix,mask,checks=0,strong=0;while(c>>ix>>mask){array<I,9>expect;for(auto&x:expect)c>>x;auto old=bank.at(ix);int n=old.size()+1,N=1<<n,F=N-1;vector<unsigned>a(n);a[0]=unsigned(mask)<<1;for(int i=1;i<n;i++)a[i]=(old[i-1]<<1)|(!(mask>>(i-1)&1));vector<I>E(N*n),S(N*n),H(N),C(N);H[0]=1;for(int i=0;i<n;i++)E[(1<<i)*n+i]=1;S[n]=1;for(int A=1;A<N;A++){for(int i=0;i<n;i++){H[A]+=E[A*n+i];unsigned todo=a[i]&~unsigned(A);while(todo){unsigned z=todo&-todo;todo-=z;int j=__builtin_ctz(z);E[(A|z)*n+j]+=E[A*n+i];S[(A|z)*n+j]+=S[A*n+i];}}}for(int A=0;A<N;A++){int B=A;while(true){C[A]+=H[B]*H[A^B];if(!B)break;B=(B-1)&A;}}I st=0,L=0,R=0,T=0;for(int A=0;A<N;A++){I sr=0;for(int i=0;i<n;i++)sr+=S[A*n+i];if(A==F)st=sr;L+=E[A*n]*H[F^A];R+=sr*H[F^A];T+=sr*C[F^A];}array<I,9>p{H[F],st,E[F*n],L,R,H[F^1],C[F],C[F^1],T};if(p!=expect){cerr<<"profile mismatch "<<ix<<" "<<mask<<endl;return 1;}if(st<=0||st>26||st%2||st%3==0)return 2;for(int j=0;j<9;j++)if(j!=1&&p[j]%3)return 3;if(L%12==6&&C[F]%12==0&&C[F^1]%12==0&&T%6==0)strong++;checks++;}cout<<"{\"literal_candidates\":"<<checks<<",\"strong_congruence_passes\":"<<strong<<"}"<<endl;}
